import { MODELS } from './modelConfig';
import { createPanelCard, createPanelGroup } from './ModelPanel.ts';

// Panels, pause rules and fullscreen live in modelPanel.ts, which the
// model embeds on description pages share. This file only handles the
// gallery paging.

// ------------------------------------------------------------
// Settings
// ------------------------------------------------------------

// Maximum number of viewports on the page at once
const PAGE_SIZE = 4;

// ------------------------------------------------------------
// Page elements
// ------------------------------------------------------------

const panelsEl = document.getElementById('panels')!;
const pagerEl = document.getElementById('pager')!;
const prevBtn = document.getElementById('prev') as HTMLButtonElement;
const nextBtn = document.getElementById('next') as HTMLButtonElement;
const pageLabel = document.getElementById('page-label')!;

const pageCount = Math.max(1, Math.ceil(MODELS.length / PAGE_SIZE));

let page = 0;

// Fullscreen layer (shared by every panel, see models.html)
const group = createPanelGroup({
    backdrop: document.getElementById('fullscreen-backdrop')!,
    controls: document.getElementById('fullscreen-controls')!,
    toggleBtn: document.getElementById('fs-toggle') as HTMLButtonElement,
    minimizeBtn: document.getElementById('fs-minimize') as HTMLButtonElement,
});

// ------------------------------------------------------------
// Pages
// ------------------------------------------------------------

// Tear down the current page and build the requested one.
function showPage(requested: number): void {

    page = Math.min(Math.max(requested, 0), pageCount - 1);

    // Closes fullscreen and releases the GPU resources of the old page.
    group.clear();

    panelsEl.replaceChildren();

    const pageModels = MODELS.slice(
        page * PAGE_SIZE,
        (page + 1) * PAGE_SIZE
    );

    for (const model of pageModels) {

        const card = createPanelCard(model);

        // Must be in the document before the viewer is created
        // so it can measure its container.
        panelsEl.append(card.section);

        group.mount(model, card);
    }

    pageLabel.textContent = `Page ${page + 1} / ${pageCount}`;

    prevBtn.disabled = page === 0;
    nextBtn.disabled = page === pageCount - 1;

    // No paging controls needed for a single page.
    pagerEl.hidden = pageCount <= 1;

    // Remember the page in the URL, so coming back from a
    // linked page (or reloading) returns to the same page.
    if (pageCount > 1) {
        history.replaceState(null, '', `#${page + 1}`);
    }
}

// ------------------------------------------------------------
// Page listeners
// ------------------------------------------------------------

// Remove these listeners again on hot reload.
const pageListeners = new AbortController();
const { signal } = pageListeners;

prevBtn.addEventListener('click', () => showPage(page - 1), { signal });
nextBtn.addEventListener('click', () => showPage(page + 1), { signal });

// ------------------------------------------------------------
// Start
// ------------------------------------------------------------

// Start on the page named in the URL (models.html#2), else page 1.
const initialPage = Number.parseInt(location.hash.slice(1), 10) - 1;

showPage(Number.isNaN(initialPage) ? 0 : initialPage);

// Change the render scale of every panel on the page at runtime
export function setRenderScale(scale: number): void {
    group.setRenderScale(scale);
}

// Clean up GPU resources when Vite hot-reloads this module
if (import.meta.hot) {
    import.meta.hot.dispose(() => {
        pageListeners.abort();
        group.destroy();
        panelsEl.replaceChildren();
    });
}